/**
 * Whether a cached pull request answer is from before the run ended, and so cannot have seen what
 * the run did on its way out.
 *
 * A run told to publish its own work opens its pull request as it finishes. The lookup cached while
 * it was still working says the branch has none, and that answer lives for a minute — long enough
  // The PR is a git host read an order of magnitude slower, so it is read through the cache and is
  // allowed to arrive late (#1028) rather than holding the whole row back on every poll.
  const pr = await linkedPr(cwd, branch, deps)
  return { branch, dirty, ...(pr.value ? { pr: pr.value } : {}), ...(pr.pending ? { prPending: true } : {}) }
}

/** The PR half of the status: the injected seam, the run-scoped history pick, or the plain view. */
async function linkedPr(
  cwd: string,
  branch: string,
  deps: GitStatusDeps,
): Promise<{ value: LinkedPr | undefined; pending: boolean }> {
  if (deps.pr) return { value: await deps.pr(cwd).catch(() => undefined), pending: false }
  if (deps.since === undefined) return cachedPrView(cwd, branch).catch(() => ({ value: undefined, pending: false }))
  if (deps.prs) return { value: pickAgentPr(await deps.prs(cwd, branch).catch(() => []), deps.since), pending: false }
  return cachedPrsForBranch(deps.prRoot ?? cwd, branch).then(
    read => ({ value: pickAgentPr(read.value ?? [], deps.since), pending: read.pending }),
    () => ({ value: undefined, pending: false }),
  )
}

import { nodeGhRunner, type GhRunner } from './gh.js'

/**
 * The project's pull requests, as one read (#1820): the ones of a branch, the open ones, the ones
 * merged since a time. One shape for every caller, OpenAgent's reads and the scheduler's
 * record alike, so nothing outside this package knows how GitHub spells a state.
 */

/** One pull request, as the command prints it. */
export interface Request {
  number: number
  url: string
  state: 'open' | 'merged' | 'closed'
  title: string
  draft: boolean
  /** The head branch's name. */
  branch: string
  /** The head commit's sha. */
  head: string
  createdAt: string
  mergedAt?: string
  /** The commit a merged request landed as on the base branch. */
  mergeCommit?: string
  /** GitHub will merge it by itself once its checks pass: auto-merge is on for it. */
  armed?: true
}

export interface RequestsQuery {
  /** Only the requests whose head is this branch. */
  branch?: string
  /** Default `all`. */
  state?: 'open' | 'merged' | 'all'
  /** Keep the requests created at or after this time; merged at or after it with `state: 'merged'`. */
  since?: string
}

/** The most requests one read answers. */
export const REQUESTS_LIMIT = 50

const FIELDS = 'number,url,state,title,isDraft,headRefName,headRefOid,createdAt,mergedAt,mergeCommit,autoMergeRequest'

/** The gh command line for a query: what the test checks, and what runs. */
export function requestsArgs(query: RequestsQuery): string[] {
  return ['pr', 'list', '--state', query.state ?? 'all', ...(query.branch ? ['--head', query.branch] : []), '--limit', String(REQUESTS_LIMIT), '--json', FIELDS]
}

interface GhRequest {
  number?: unknown
  url?: unknown
  state?: unknown
  title?: unknown
  isDraft?: unknown
  headRefName?: unknown
  headRefOid?: unknown
  createdAt?: unknown
  mergedAt?: unknown
  mergeCommit?: { oid?: unknown } | null
  autoMergeRequest?: unknown
}

